import { I, dish } from "./catalog-kit.ts";
import type { Recipe, RecipeSource } from "./types";

const foreign365: RecipeSource = {
  book: "365 Foreign Dishes",
  author: "Anonymous",
  year: 1908,
  era: "1900s",
  archiveId: "365foreigndishes00newy",
  credit: "365 Foreign Dishes (George W. Jacobs, 1908). Project Gutenberg. Public domain.",
};

function h(
  id: string,
  name: string,
  cuisine: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  nutrition: Recipe["nutrition"],
): Recipe {
  return dish({
    id, name, cuisine, description, minutes, protein, plate,
    tags: Array.from(new Set(["vintage", "book-365-foreign", "era-1900s", "international", ...tags])),
    ingredients, steps, nutrition, source: foreign365,
  });
}

